const scrollReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const headings=[...document.querySelectorAll('.section-head h2')];
headings.forEach(h=>{const lines=h.innerHTML.split(/<br\s*\/?\s*>/i);h.innerHTML=lines.map(line=>'<span class="heading-line"><span class="heading-inner">'+line+'</span></span>').join('');});
const chaptersScroll=[['club','L’esprit du club'],['cours','Trouver sa voie'],['horaires','Son dojo, son créneau'],['tarifs','Prendre sa place'],['actions','Grandir ensemble'],['contact','Rejoindre le tatami']];const tracker=document.querySelector('.chapter-tracker');
const manifesto=document.querySelector('.scroll-manifesto'),lines=[...document.querySelectorAll('.manifesto-sticky h2 span')];let framePending=false;
const clamp=v=>Math.max(0,Math.min(1,v));
function revealProgress(el){const r=el.getBoundingClientRect();return clamp((innerHeight*.87-r.top)/Math.min(innerHeight*.45,Math.max(100,r.height)));}
function updatePageMotion(){framePending=false;const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress i').style.transform=`scaleX(${max>0?scrollY/max:0})`;const r=manifesto.getBoundingClientRect(),p=clamp(-r.top/Math.max(1,r.height-innerHeight));lines.forEach((line,i)=>line.style.setProperty('--word-progress',scrollReduced?1:clamp((p*4-i)*1.7+.12)));let chapterIndex=-1;chaptersScroll.forEach(([id],i)=>{if(document.getElementById(id).getBoundingClientRect().top<innerHeight*.52)chapterIndex=i});tracker.classList.toggle('show',chapterIndex>=0);if(chapterIndex>=0){const next=Math.min(chapterIndex+1,chaptersScroll.length-1);tracker.querySelector('.chapter-count').textContent='0'+(chapterIndex+1)+' / 06';tracker.querySelector('.chapter-label').textContent=chaptersScroll[chapterIndex][1];tracker.href='#'+chaptersScroll[next][0];tracker.setAttribute('aria-label','Chapitre '+(chapterIndex+1)+' : '+chaptersScroll[chapterIndex][1]+'. Aller à '+chaptersScroll[next][1]);}if(scrollReduced)return;
headings.forEach(h=>h.style.setProperty('--heading-progress',revealProgress(h)));
document.querySelectorAll('.course-card').forEach(card=>card.style.setProperty('--card-progress',revealProgress(card)));
document.querySelectorAll('.action-list article').forEach(article=>article.style.setProperty('--action-progress',revealProgress(article)));
const contact=document.querySelector('.contact');contact.style.setProperty('--contact-progress',revealProgress(contact));
const strip=document.querySelector('.values-strip');strip.style.setProperty('--marquee-shift',Math.max(-70,Math.min(70,(strip.getBoundingClientRect().top-innerHeight*.5)*-.12))+'px');
document.querySelectorAll('.club-photo,.action-photo').forEach(card=>{const b=card.getBoundingClientRect();const t=Math.max(-1,Math.min(1,(b.top+b.height/2-innerHeight/2)/innerHeight));card.style.setProperty('--image-shift',t*-18+'px');});}
addEventListener('scroll',()=>{if(!framePending){framePending=true;requestAnimationFrame(updatePageMotion)}},{passive:true});addEventListener('resize',updatePageMotion);updatePageMotion();
// Count only once when the club figures enter view; preserve the dated qualification.
const statNumbers=[...document.querySelectorAll('.stats b')];if(!scrollReduced){const counter=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;counter.unobserve(e.target);const original=e.target.textContent,target=parseInt(original,10),suffix=original.replace(/^\d+/,'');if(!Number.isFinite(target))return;const start=performance.now();function tick(now){const p=clamp((now-start)/1100);e.target.textContent=Math.round(target*(1-Math.pow(1-p,3)))+suffix;if(p<1)requestAnimationFrame(tick);else e.target.textContent=original;}requestAnimationFrame(tick);}),{threshold:.7});statNumbers.forEach(n=>counter.observe(n));}
